insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-18','verbeterd','Offertes','Een verkoopkans herinnert je aan zichzelf',
   'Zet je een verkoopkans een half jaar vooruit, dan hoef je die datum niet meer te onthouden. De actiehouder krijgt ''s ochtends een melding zodra een kans vandaag aan de beurt is of over de datum heen. De melding brengt je rechtstreeks naar het Aanvragen-tab, waar alle kansen staan.');
